SELECT (DATE_TRUNC('HOUR', "LOAD_HOUR")) AS "TIME_BUCKET", (CAST(CASE WHEN (SUM(ELAPSED_MS)) = 0 OR (SUM(ELAPSED_MS)) IS NULL THEN NULL ELSE CAST((SUM(QUEUED_OVERLOAD_MS)) AS DECIMAL(38, 15)) / CAST((SUM(ELAPSED_MS)) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "WH_QUEUE_OVERLOAD_PCT" FROM (SELECT "WAREHOUSE_NAME" AS WAREHOUSE_NAME, (DATE_TRUNC('HOUR', (TRY_TO_TIMESTAMP_NTZ("START_TIME")))) AS LOAD_HOUR, (NULL) AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). Grouped on, */ /* so two accounts running a warehouse of the same name in the same hour */ /* stay two rows rather than one merged average. */, COUNT(*) AS QUERY_COUNT, SUM("QUEUED_OVERLOAD_TIME") AS QUEUED_OVERLOAD_MS, SUM("QUEUED_PROVISIONING_TIME") AS QUEUED_PROVISIONING_MS, SUM("TOTAL_ELAPSED_TIME") AS ELAPSED_MS, SUM("EXECUTION_TIME") AS EXECUTION_MS FROM query_history GROUP BY 1, 2, 3) AS base GROUP BY (DATE_TRUNC('HOUR', "LOAD_HOUR")) ORDER BY "WH_QUEUE_OVERLOAD_PCT" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
